@override
Widget build(BuildContext context) {
  ref.listen<AsyncValue>(
    authNotifierProvider,
    (_, state) => state.showAlertDialogOnError(context),
  );
  final state = ref.watch(authNotifierProvider);
  return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.black,
        toolbarHeight: 0,
      ),
      body: GestureDetector(
        onTap: () {
          FocusScope.of(context).unfocus();
        },
        child: Container(
          alignment: Alignment.center,
          margin: 10.horizontalPadding,
          child: Center(
            child: ResponsiveScrollableCard(
              child: FocusScope(
                node: _node,
                child: Form(
                  key: _formKey,
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: <Widget>[
                      15.height,

                      TextFormField(
                        controller: _email,
                        decoration: const InputDecoration(
                            hintText: AppLabels.email,
                            prefixIcon: Icon(Icons.person)),
                        autovalidateMode: AutovalidateMode.onUserInteraction,
                        validator: (email) => !_submitted
                            ? null
                            : (email!.isEmpty ? AppLabels.emptyEmail : null),
                        inputFormatters: <TextInputFormatter>[
                          ValidatorInputFormatter(
                              editingValidator: EmailEditingRegexValidator()),
                        ],
                        autocorrect: false,
                        textInputAction: TextInputAction.next,
                        keyboardType: TextInputType.emailAddress,
                        keyboardAppearance: Brightness.light,
                      ),
                      8.height,
                      // Password field
                      TextFormField(
                        controller: _passwordController,
                        decoration: InputDecoration(
                          hintText: AppLabels.password,
                          prefixIcon: const Icon(Icons.lock),
                          suffixIcon: GestureDetector(
                              onTap: () {
                                setState(() {
                                  _passwordVisible = !_passwordVisible;
                                });
                              },
                              child: _passwordVisible
                                  ? const Icon(Icons.visibility_off)
                                  : const Icon(Icons.visibility)),
                        ),
                        validator: (password) => !_submitted
                            ? null
                            : (password!.isEmpty
                                ? AppLabels.emptyPassword
                                : null),
                        autovalidateMode: AutovalidateMode.onUserInteraction,
                        obscureText: _passwordVisible ? true : false,
                        autocorrect: false,
                        textInputAction: TextInputAction.done,
                        keyboardAppearance: Brightness.light,
                        onEditingComplete: () => _passwordEditingComplete(),
                      ),

                      8.height,
                      PrimaryButton(
                        text: _loginType ? AppLabels.login : AppLabels.signUp,
                        isLoading: state.isLoading,
                        onPressed:
                            state.isLoading ? () => {} : () => _submit(),
                      ),

                      8.height,

                      Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Text(!_loginType
                              ? 'Already account?'
                              : 'Create an account'),
                          CustomTextButton(
                            text: _loginType
                                ? AppLabels.signUp
                                : AppLabels.login,
                            style: const TextStyle(
                                decoration: TextDecoration.underline),
                            onPressed: _changeFormType,
                          ),
                        ],
                      )
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ));
}

onPressedOk: () async {
  final authNotifier =
      ref.read(authNotifierProvider.notifier);
  final success = await authNotifier.logout();
  if (success && mounted) {
    context.replaceNamed(AppRoute.login.name);
  }
});
